/** The mock response for a public GET path, or undefined: lets a page swap mocks for the real API in one place. */
export function mockGet(path: string): unknown {
  const match = /^\/api\/matches\/(\d+)$/.exec(path)
  if (match) return mockMatches[Number(match[1])]
  switch (path) {
    case '/api/tournaments/1':
      return mockTournament
    case '/api/tournaments/1/table':
      return mockPointsTable
    case '/api/tournaments/1/leaderboards':
      return mockLeaderboards
  }
  return undefined
}
